/* Toggle Switch Styles */
input:checked~.dot {
    transform: translateX(100%);
    background-color: #48bb78;
}

input:checked~.block {
    background-color: #a7f3d0;
}

/* Payment Modal Styles */
.payment-modal {
    display: none;
    position: fixed;
    z-index: 50;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    overflow: auto;
    background-color: rgba(0, 0, 0, 0.4);
}

.payment-modal-content {
    background-color: #fff;
    margin: 5% auto;
    padding: 24px;
    border: none;
    width: 90%;
    max-width: 800px;
    border-radius: 1rem;
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
}

.close-modal {
    color: #6b7280;
    font-size: 1.75rem;
    font-weight: 700;
    cursor: pointer;
}

.close-modal:hover,
.close-modal:focus {
    color: #1f2937;
}



