        if (thu === 8) return 'Chủ nhật';
        return `Thứ ${thu}`;
    };

    const formatScheduleDetail = (details) => {
        if (!details || details.error || !Array.isArray(details) || details.length === 0) {
            return 'Không có thông tin lịch học';
        }
        return details.map(d => `
